                url: eventUrl
            }).then(() => {
            }).catch((error) => {
                fallbackShare(eventTitle, eventUrl);
            });
        } else {
            // 폴백: 클립보드 복사 또는 공유 옵션 표시
            fallbackShare(eventTitle, eventUrl);
